declare
  d constant jsonb := $content${"units":[{"id":"a1-u01","language_code":"en","level":"A1","position":1,"title_es":"Saludos y presentaciones","title_en":"Greetings and introductions","description_es":"Saludar, despedirte, ser amable y presentarte.","emoji":"👋","objective_es":"Podés saludar según el momento del día, presentarte, preguntar cómo está alguien y responder con cortesía.","grammar":{"title":"My name is… / I am…","explanation":"Para decir tu nombre usás my name is o I am (I'm). Para devolver un saludo agregás too: nice to meet you too.","examples":[{"target":"My name is Tom.","base":"Mi nombre es Tom."},{"target":"I'm fine, thank you.","base":"Estoy bien, gracias."}]},"review_status":"draft"},{"id":"a1-u02","language_code":"en","level":"A1","position":2,"title_es":"Pronombres y verbo to be","title_en":"Pronouns and the verb to be","description_es":"Yo, vos, él, ella… y cómo decir quién sos y cómo estás.","emoji":"🧍","objective_es":"Podés usar los pronombres y el verbo to be para decir quién sos, cómo estás y hablar de otras personas.","grammar":{"title":"To be: am, is, are","explanation":"To be es «ser» y «estar» a la vez. I am; you, we y they are; he, she e it is. Para negar se agrega not y para preguntar el verbo va primero.","examples":[{"target":"I'm a student.","base":"Soy estudiante."},{"target":"She is not tired.","base":"Ella no está cansada."},{"target":"Are you happy?","base":"¿Estás feliz?"}]},"review_status":"draft"},{"id":"a1-u03","language_code":"en","level":"A1","position":3,"title_es":"Números, edades y países","title_en":"Numbers, ages and countries","description_es":"Contar hasta veinte, decir tu edad y de dónde sos.","emoji":"🌍","objective_es":"Podés contar hasta veinte, decir tu edad y de dónde sos.","grammar":{"title":"La edad con to be","explanation":"En inglés la edad va con to be, no con have: I am ten (years old). El origen también: I am from Argentina.","examples":[{"target":"How old are you?","base":"¿Cuántos años tenés?"},{"target":"I'm twenty years old.","base":"Tengo veinte años."},{"target":"Where are you from?","base":"¿De dónde sos?"}]},"review_status":"draft"},{"id":"a1-u04","language_code":"en","level":"A1","position":4,"title_es":"Familia y personas","title_en":"Family and people","description_es":"Presentar a tu familia y hablar de otras personas.","emoji":"👨‍👩‍👧","objective_es":"Podés presentar a tu familia, decir de quién es algo con his, her, our y their, y cuántos familiares tenés.","grammar":{"title":"His / her y have / has","explanation":"His es «su» de él y her, «su» de ella: depende de quién es dueño. Tener es have, pero con he, she e it es has.","examples":[{"target":"Her brother is ten.","base":"Su hermano (de ella) tiene diez años."},{"target":"I have two sisters.","base":"Tengo dos hermanas."},{"target":"He has a baby.","base":"Él tiene un bebé."}]},"review_status":"draft"},{"id":"a1-u05","language_code":"en","level":"A1","position":5,"title_es":"Objetos cotidianos","title_en":"Everyday objects","description_es":"Nombrar objetos, señalar cosas cerca y lejos, y describir colores y tamaños.","emoji":"🎒","objective_es":null,"grammar":null,"review_status":"draft"},{"id":"a1-u06","language_code":"en","level":"A1","position":6,"title_es":"Casa y habitaciones","title_en":"Home and rooms","description_es":"Describir tu casa, sus habitaciones y dónde están las cosas.","emoji":"🏠","objective_es":null,"grammar":null,"review_status":"draft"},{"id":"a1-u07","language_code":"en","level":"A1","position":7,"title_es":"Comida y bebidas","title_en":"Food and drinks","description_es":"Pedir comida, decir qué querés y hablar de las comidas del día.","emoji":"🍎","objective_es":null,"grammar":null,"review_status":"draft"},{"id":"a1-u08","language_code":"en","level":"A1","position":8,"title_es":"Rutinas y presente simple","title_en":"Routines and present simple","description_es":"Contar qué hacés todos los días, preguntar y negar en presente.","emoji":"⏰","objective_es":null,"grammar":null,"re